#include <iostream>
#include <fstream>
#include <vector>
#include <set>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int maxLen = 0, maxStart = 0;
    for (int i = 0; i < (int)dane.size(); i++) {
        set<int> seen;
        int j;
        for (j = i; j < (int)dane.size(); j++) {
            if (seen.count(dane[j])) break;
            seen.insert(dane[j]);
        }
        int len = j - i;
        if (len > maxLen) {
            maxLen = len;
            maxStart = i;
        }
    }
    cout << "Najdluzszy podciag bez powtorzen: " << maxLen << " elementow" << endl;
    cout << "Poczatek: pozycja " << maxStart + 1 << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxLen; i++) {
        cout << " " << dane[i];
    }
    cout << endl;
    return 0;
}
```

